export class CdnPurgeService {
  // BUG: Polling-based invalidation with URL wildcard scanning
  public async purgeByPrefix(prefix: string): Promise<void> {
    const edges = await this.getEdgeNodes();
    for (const edge of edges) {
      await fetch(`${edge}/purge?prefix=${prefix}`, { method: 'POST' });
    }
  }
}

